package com.lexiscan.analysis; import com.lexiscan.document.Document; import jakarta.persistence.*; import lombok.*; import java.util.*;
@Entity @Table(name="clauses") @Getter @Setter @NoArgsConstructor public class Clause { @Id private UUID id=UUID.randomUUID(); @ManyToOne(optional=false) @JoinColumn(name="document_id") private Document document; @Column(name="clause_index") private int clauseIndex; @Column(name="clause_text",columnDefinition="TEXT") private String clauseText; private String category; @Column(name="risk_level") private String riskLevel; @Column(name="risk_score") private int riskScore; @Column(name="risk_reason") private String riskReason; }
